CREATE TEMPORARY VIEW dws_abs_${grass_region_without_quote} AS
SELECT
    user_id
    ,feature_group
    ,COALESCE(ads_gmv_usd / ads_order_cnt, 0) AS abs
    ,COALESCE(broad_gmv_usd / ads_broad_order_cnt, 0) AS broad_abs
FROM
    dws_ads_performance_extended_${grass_region_without_quote};

--sql_divide_splitter--

CREATE TEMPORARY VIEW approx_pct_${grass_region_without_quote} AS
SELECT
    feature_group
    ,APPROX_PERCENTILE(IF(abs > 0, abs, ''), ARRAY(0.95,0.99,0.995,0.999)) AS abs_pct
    ,APPROX_PERCENTILE(IF(broad_abs > 0, broad_abs, ''), ARRAY(0.95,0.99,0.995,0.999)) AS broad_abs_pct
FROM
    dws_abs_${grass_region_without_quote}
GROUP BY
    1;

