INSERT OVERWRITE TABLE ${schema}.ads_sr_data_warehouse_platform_feature_group_ads_outlier_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
    feature_group
    ,'direct_ads_abs' AS outlier_type
    ,case
        WHEN pos = 0 THEN 0.95
        WHEN pos = 1 THEN 0.99
        WHEN pos = 2 THEN 0.995
        WHEN pos = 3 THEN 0.999
    ELSE NULL END AS percentile
    ,val
FROM
    approx_pct_${grass_region_without_quote}
LATERAL VIEW
    POSEXPLODE(abs_pct) AS pos, val
UNION ALL
SELECT
    feature_group
    ,'broad_ads_abs' AS outlier_type
    ,case
        WHEN pos = 0 THEN 0.95
        WHEN pos = 1 THEN 0.99
        WHEN pos = 2 THEN 0.995
        WHEN pos = 3 THEN 0.999
    ELSE NULL END AS percentile
    ,val
FROM
    approx_pct_${grass_region_without_quote}
LATERAL VIEW
    POSEXPLODE(broad_abs_pct) AS pos, val;
